 function comparisonGrid(shapes,labels,scale=35){
  const cols=shapes.length===4?2:3,rows=Math.ceil(shapes.length/cols),w=600,h=rows*180;
  return svg(shapes.map((p,i)=>{const x=(i%cols+.5)*w/cols,y=Math.floor(i/cols)*180+82;return poly(p.map(([u,v])=>[x+u*scale,y-v*scale]))+text([x,y+79],labels[i],'style="font-size:23px"')}).join(''),w,h);
 }
